static const struct CS2_OpcodeMeta cs2_opcode_meta_unknown = {
    "_unknown", CS2_OPERAND_INT32, CS2_HANDLER_HOST, CS2_OPCODE_GROUP_UNKNOWN, -1
};

const struct CS2_OpcodeMeta*
cs2_opcode_meta_lookup(int opcode)
{
    if( opcode < 0 || opcode >= CS2_OP_COUNT )
        return &cs2_opcode_meta_unknown;
    return &cs2_opcode_meta_table[opcode];
}

enum CS2_OperandKind
cs2_opcode_operand_kind(int opcode)
{
    return cs2_opcode_meta_lookup(opcode)->operand;
}

const char*
CS2_OpCode_String(int opcode)
{
    return cs2_opcode_meta_lookup(opcode)->name;
}

enum CS2_OpcodeGroup
CS2_WireOpcodeGroupOf(int wire)
{
    if( (wire >= 0 && wire < 100) )
        return CS2_OPCODE_GROUP_VM_CORE;
    if( (wire >= 100 && wire < 1000) )
        return CS2_OPCODE_GROUP_COMPONENT;
    if( (wire >= 1000 && wire < 1100) || (wire >= 2000 && wire < 2100) )
        return CS2_OPCODE_GROUP_COMPONENT_LAYOUT;
    if( (wire >= 1100 && wire < 1200) || (wire >= 2100 && wire < 2200) )
        return CS2_OPCODE_GROUP_COMPONENT_APPEARANCE;
    if( (wire >= 1200 && wire < 1300) || (wire >= 2200 && wire < 2300) )
        return CS2_OPCODE_GROUP_COMPONENT_MODEL;
    if( (wire >= 1300 && wire < 1400) || (wire >= 2300 && wire < 2400) )
        return CS2_OPCODE_GROUP_COMPONENT_OP;
    if( (wire >= 1400 && wire < 1500) || (wire >= 2400 && wire < 2500) )
        return CS2_OPCODE_GROUP_COMPONENT_LISTENER;
    if( (wire >= 1500 && wire < 1600) )
        return CS2_OPCODE_GROUP_CC_GEOMETRY;
    if( (wire >= 1600 && wire < 1700) )
        return CS2_OPCODE_GROUP_CC_APPEARANCE;
    if( (wire >= 1700 && wire < 1800) )
        return CS2_OPCODE_GROUP_CC_INVENTORY;
    if( (wire >= 1800 && wire < 1900) )
        return CS2_OPCODE_GROUP_CC_TARGET;
    if( (wire >= 1900 && wire < 2000) || (wire >= 2900 && wire < 3000) )
        return CS2_OPCODE_GROUP_COMPONENT_ACTION;
    if( (wire >= 2500 && wire < 2600) )
        return CS2_OPCODE_GROUP_IF_GEOMETRY;
    if( (wire >= 2600 && wire < 2700) )
        return CS2_OPCODE_GROUP_IF_APPEARANCE;
    if( (wire >= 2700 && wire < 2800) )
        return CS2_OPCODE_GROUP_IF_INVENTORY;
    if( (wire >= 2800 && wire < 2900) )
        return CS2_OPCODE_GROUP_IF_TARGET;
    if( (wire >= 3000 && wire < 3200) )
        return CS2_OPCODE_GROUP_CLIENT;
    if( (wire >= 3200 && wire < 3300) )
        return CS2_OPCODE_GROUP_AUDIO_OPTIONS;
    if( (wire >= 3300 && wire < 3400) )
        return CS2_OPCODE_GROUP_CLIENT_STATE;
    if( (wire >= 3400 && wire < 3500) )
        return CS2_OPCODE_GROUP_ENUM;
    if( (wire >= 3500 && wire < 3600) )
        return CS2_OPCODE_GROUP_KEYBOARD;
    if( (wire >= 3600 && wire < 3700) )
        return CS2_OPCODE_GROUP_SOCIAL;
    if( (wire >= 3700 && wire < 3800) )
        return CS2_OPCODE_GROUP_UNUSED_3700;
    if( (wire >= 3800 && wire < 3900) )
        return CS2_OPCODE_GROUP_CLAN;
    if( (wire >= 3900 && wire < 4000) )
        return CS2_OPCODE_GROUP_MARKET;
    if( (wire >= 4000 && wire < 4100) )
        return CS2_OPCODE_GROUP_MATH;
    if( (wire >= 4100 && wire < 4200) )
        return CS2_OPCODE_GROUP_STRING;
    if( (wire >= 4200 && wire < 4300) )
        return CS2_OPCODE_GROUP_OBJ;
    if( (wire >= 4300 && wire < 5100) )
        return CS2_OPCODE_GROUP_CHAT;
    if( (wire >= 5100 && wire < 5400) )
        return CS2_OPCODE_GROUP_WINDOW;
    if( (wire >= 5400 && wire < 5600) )
        return CS2_OPCODE_GROUP_CAMERA;
    if( (wire >= 5600 && wire < 5700) )
        return CS2_OPCODE_GROUP_LOGIN;
    if( (wire >= 5700 && wire < 6300) )
        return CS2_OPCODE_GROUP_VIEWPORT;
    if( (wire >= 6300 && wire < 6600) )
        return CS2_OPCODE_GROUP_WORLD;
    if( (wire >= 6600 && wire < 6700) )
        return CS2_OPCODE_GROUP_WORLDMAP;
    if( (wire >= 6700 && wire < 6800) )
        return CS2_OPCODE_GROUP_CLIENTOP_NPC;
    if( (wire >= 6800 && wire < 6900) )
        return CS2_OPCODE_GROUP_CLIENTOP_LOC;
    if( (wire >= 6900 && wire < 7000) )
        return CS2_OPCODE_GROUP_CLIENTOP_PLAYER;
    if( (wire >= 7000 && wire < 7100) )
        return CS2_OPCODE_GROUP_HIGHLIGHT;
    if( (wire >= 7100 && wire < 7200) )
        return CS2_OPCODE_GROUP_MINIMENU;
    if( (wire >= 7200 && wire < 7500) )
        return CS2_OPCODE_GROUP_OVERLAY;
    if( (wire >= 7500 && wire < 7600) )
        return CS2_OPCODE_GROUP_DB;
    if( (wire >= 7600 && wire < 7700) )
        return CS2_OPCODE_GROUP_LOOT;
    if( (wire >= 7700 && wire < 8000) )
        return CS2_OPCODE_GROUP_EXTENSION;
    if( (wire >= 8000 && wire < 8100) )
        return CS2_OPCODE_GROUP_ARRAY;
    if( (wire >= 8100 && wire < 8600) )
        return CS2_OPCODE_GROUP_TYPED_DATA;
    if( (wire >= 13000 && wire < 14000) )
        return CS2_OPCODE_GROUP_OP_COUNT;
    return CS2_OPCODE_GROUP_UNKNOWN;
}

enum CS2_OpcodeGroup
CS2_OpcodeGroupOf(int opcode)
{
    return cs2_opcode_meta_lookup(opcode)->group;
}

